// Keep every core route usable even when client-side hydration is delayed or unavailable.
// Native anchors provide a reliable full-page navigation fallback in every browser.
function Link({ children, ...props }: React.AnchorHTMLAttributes<HTMLAnchorElement> & { href: string }) {
  return <a {...props}>{children}</a>;
}

type View = "home"|"access"|"shop"|"product"|"coa"|"account"|"partner"|"ops"|"research"|"subscribe"|"partners"|"about"|"support"|"cart"|"checkout"|"bundle"|"tracking"|"compare"|"bulk"|"rewards"|"guarantee";

type CartItem = { id:string; slug:string; name:string; strength:string; unitPrice:number; qty:number; tone:Product["tone"]; bundle?:boolean };
// Isolate the new source-priced cart from legacy demo variants and discounts.
const CART_KEY="pow_demo_cart_inventory_2026_09_08";
const SAVED_KEY="pow_demo_saved";
function itemTotal(item:CartItem){return Math.round(item.unitPrice*item.qty*100)/100}
function readCart():CartItem[]{try{return JSON.parse(localStorage.getItem(CART_KEY)||"[]")}catch{return []}}
function saveCart(items:CartItem[]){localStorage.setItem(CART_KEY,JSON.stringify(items));window.dispatchEvent(new Event("pow-cart-change"))}
function addCartItem(item:CartItem){const items=readCart();const found=items.find(x=>x.id===item.id);if(found)found.qty+=item.qty;else items.push(item);saveCart(items)}
function useDemoCart(){
  const [items,setItems]=useState<CartItem[]>([]);
  useEffect(()=>{const sync=()=>setItems(readCart());sync();window.addEventListener("storage",sync);window.addEventListener("pow-cart-change",sync);return()=>{window.removeEventListener("storage",sync);window.removeEventListener("pow-cart-change",sync)}},[]);
  return {items,set:(next:CartItem[])=>saveCart(next),count:items.reduce((n,x)=>n+x.qty,0)};
}
function useSavedProducts(){
  const [saved,setSaved]=useState<string[]>([]);
  useEffect(()=>{const timer=window.setTimeout(()=>{try{setSaved(JSON.parse(localStorage.getItem(SAVED_KEY)||"[]"))}catch{setSaved([])}},0);return()=>window.clearTimeout(timer)},[]);
  const toggle=(slug:string)=>setSaved(current=>{const next=current.includes(slug)?current.filter(x=>x!==slug):[...current,slug];localStorage.setItem(SAVED_KEY,JSON.stringify(next));return next});
  return {saved,toggle};
}

function useReferralCapture() {
  const [referral, setReferral] = useState("");
  useEffect(() => {
    const query = new URLSearchParams(window.location.search);
    const incoming = query.get("ref") || query.get("partner");
    if (incoming) localStorage.setItem("pow_referral", incoming);
    const timer = window.setTimeout(() => setReferral(incoming || localStorage.getItem("pow_referral") || ""), 0);
    return () => window.clearTimeout(timer);
  }, []);
  return referral;
}

