  const eligible=products.filter(p=>p.subscription); const [slug,setSlug]=useState(eligible[0].slug); const [cadence,setCadence]=useState(4); const [qty,setQty]=useState(1); const selected=eligible.find(p=>p.slug===slug)||eligible[0];
