function PartnersView(){
  const [handle,setHandle]=useState("your-name"); const [destination,setDestination]=useState("/"); const [campaign,setCampaign]=useState("welcome"); const [copied,setCopied]=useState(false); const [submitted,setSubmitted]=useState(false);
  const cleanHandle=(handle||"your-name").toLowerCase().trim().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"")||"your-name";
  const cleanCampaign=(campaign||"welcome").toLowerCase().trim().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"")||"welcome";
  const partnerLink=`powpeptides.com/r/${cleanHandle}?to=${destination}&campaign=${cleanCampaign}`;
  const copyPartnerLink=()=>{navigator.clipboard?.writeText(`https://${partnerLink}`);setCopied(true);setTimeout(()=>setCopied(false),1600)};
  const steps=[
    ["01","Apply","Tell POW who you are, how you reach your audience, and where you plan to share."],
    ["02","Get approved","Review the program rules, complete the required profile, and receive your unique partner handle."],
    ["03","Create your link","Choose the homepage, a category, or a product. Add a campaign label so you know what worked."],
    ["04","Share it","Use your link in permission-based email, SMS, social, QR, or one-to-one customer conversations."],
    ["05","Track the sale","The portal connects eligible activity to your link and shows pending, approved, paid, or reversed commission events."]
  ];
  return <main><Header/><section className="partner-network-hero"><div><span className="impact-label">POW! Partner Network</span><h1>Build trust.<br/>Share the POW.<br/><em>Get credit.</em></h1><p>Give your audience a direct path into the POW! storefront with your own tracked link. When eligible customers shop through it, the Partner Command Center keeps clicks, customers, orders, and commission status in one place.</p><div className="partner-hero-actions"><a className="button primary" href="#apply">Start your application <span>↓</span></a><Link className="button ghost" href="/partner">Open the command center</Link></div><small>APPLICATION, ATTRIBUTION, AND COMMISSION TERMS SHOWN HERE ARE A FUNCTIONAL PROTOTYPE.</small></div><aside className="partner-pass"><span>PARTNER ID / YOUR-NAME</span><img src="/brand-assets/svg/pow-logo-primary.svg" alt="POW! Peptides"/><b>SHARE.<br/>TRACK.<br/>EARN.</b><small>ONE LINK · ONE PORTAL · CLEAR CREDIT</small></aside></section><section className="partner-value-strip"><span><b>01</b> No storefront to manage</span><span><b>02</b> Product-level links</span><span><b>03</b> Approved creative</span><span><b>04</b> Attribution visibility</span></section>
    <section className="partner-promise"><div><span>WHY PARTNER WITH POW!?</span><h2>Your audience stays yours.<br/><em>The shopping gets easier.</em></h2><p>You bring the relationship. POW provides the destination, product catalog, proof experience, checkout path, and partner reporting. Your tracked link is the connection between the two.</p></div><div className="partner-benefit-grid">{[["YOUR LINK","A durable partner URL plus optional product and campaign links."],["YOUR CREATIVE","Approved messages and formats built for email, SMS, social, and print."],["YOUR VISIBILITY","See attributed clicks, masked customers, orders, renewals, and commission states."],["YOUR SUPPORT","One place for program rules, payout history, and partner questions."]].map((x,i)=><article key={x[0]}><span>0{i+1}</span><h3>{x[0]}</h3><p>{x[1]}</p></article>)}</div></section>
    <section className="partner-steps" id="how-it-works"><header><span>FROM APPLICATION TO ATTRIBUTION</span><h2>Five steps.<br/>One clean path.</h2><p>You do not need to build a shop or learn a new sales system. Set up the relationship once, then send customers through your POW! link.</p></header><div>{steps.map(x=><article key={x[0]}><span>{x[0]}</span><div><h3>{x[1]}</h3><p>{x[2]}</p></div></article>)}</div></section>
    <section className="partner-link-lab"><div className="partner-link-copy"><span>GUIDED SETUP / 01</span><h2>Build your<br/><em>first link.</em></h2><p>Every partner starts with one memorable base link. Create focused versions when you want to send customers to a specific product or measure a specific campaign.</p><ol><li><b>Choose your handle.</b> This identifies your account.</li><li><b>Pick a destination.</b> Send people where the message promises.</li><li><b>Name the campaign.</b> Keep email, SMS, and social results separate.</li><li><b>Copy and share.</b> Use the exact generated URL.</li></ol></div><div className="partner-link-builder"><span>BUILD YOUR FIRST LINK</span><label>Partner handle<input value={handle} onChange={e=>setHandle(e.target.value)} placeholder="your-name"/></label><label>Customer destination<select value={destination} onChange={e=>setDestination(e.target.value)}><option value="/">POW! homepage</option><option value="/shop">Shop all compounds</option>{products.slice(0,4).map(p=><option value={`/shop/${p.slug}`} key={p.slug}>{p.name} · {p.strength}</option>)}</select></label><label>Campaign label<input value={campaign} onChange={e=>setCampaign(e.target.value)} placeholder="welcome"/></label><div className="generated-link"><span>YOUR TRACKED LINK</span><code>{partnerLink}</code><button onClick={copyPartnerLink}>{copied?"Copied ✓":"Copy link"}</button></div><small>DEMO BUILDER · A production link becomes active only after partner approval.</small></div></section>
    <section className="partner-share-playbook"><header><span>YOUR CUSTOMER DATABASE / 02</span><h2>Share it where<br/>trust already lives.</h2><p>Use the same tracked destination across the channels your audience has already chosen. Keep the message useful, permission-based, and built from POW-approved claims and creative.</p></header><div className="share-channel-grid"><article><span>EMAIL</span><h3>Email your list.</h3><p>Introduce POW, explain why it is relevant, and give one obvious button linked to the most useful destination.</p><div><b>Subject</b><span>A research source worth knowing</span><b>Button</b><span>Shop through my POW! link →</span></div></article><article><span>SMS</span><h3>Text opted-in customers.</h3><p>Keep it short: one useful reason to click, one tracked link, and the required opt-out language.</p><div><b>Message</b><span>I partnered with POW! Explore the research lineup here: [YOUR LINK]</span></div></article><article><span>SOCIAL + QR</span><h3>Post approved creative.</h3><p>Use your link in bio, stories, posts, printed materials, or a QR code. Name each campaign so the portal can separate the traffic.</p><div><b>Rule</b><span>Use approved assets. Never add medical promises or unsupported product claims.</span></div></article></div><p className="permission-note"><b>Permission matters.</b> Only contact people who have opted in, identify the sender, honor unsubscribes, and follow the rules that apply to the channel and audience.</p></section>
    <section className="partner-attribution"><div><span>WHAT HAPPENS AFTER THE CLICK?</span><h2>The link carries<br/><em>your credit.</em></h2><p>The customer shops on POW—not inside a separate store you have to maintain. The referral event connects their eligible activity to your partner account according to the approved program rules.</p><Link className="button primary" href="/partner">Preview the command center</Link></div><div className="attribution-board"><span>CLICK → CUSTOMER → ORDER → COMMISSION</span>{[["01","CLICK","Your partner and campaign IDs arrive with the customer."],["02","CUSTOMER","Eligible attribution is recorded with privacy-minded customer masking."],["03","ORDER","Qualifying purchases and renewals create ledger events."],["04","REVIEW","Refunds, holds, and eligibility rules determine final status."],["05","PAYOUT","Approved commission moves into the payout history."]].map(x=><div key={x[0]}><i>{x[0]}</i><b>{x[1]}</b><p>{x[2]}</p></div>)}</div></section>
    <section className="partner-rules-preview"><div><span>NO BLACK BOX</span><h2>Know what every<br/>status means.</h2></div><div>{[["PENDING","The order is recorded and waiting for the program review window."],["APPROVED","The sale meets the current eligibility rules and is queued for payout."],["PAID","The commission is included in a completed payout record."],["REVERSED","A refund, cancellation, duplicate, or rule exception removed the credit."]].map(x=><article key={x[0]}><span className={`status-chip ${x[0].toLowerCase()}`}>{x[0]}</span><p>{x[1]}</p></article>)}</div><small>Attribution window, commission rates, eligible sales, payout timing, minimums, tax requirements, and reversal rules remain POW program decisions.</small></section>
    <section className="partner-apply" id="apply"><div><span>APPLICATION / 03</span><h2>Start your partner<br/><em>application.</em></h2><p>Give POW enough context to understand your audience and how you plan to introduce the brand. A production version would route this to partner review.</p><ul><li>Audience and primary channels</li><li>Business or creator profile</li><li>Planned promotion method</li><li>Program terms acknowledgment</li></ul></div><div className="partner-application-card">{submitted?<div className="partner-application-success"><span>APPLICATION CAPTURED / DEMO</span><h3>You&apos;re on the list.</h3><p>No application was transmitted. In production, POW would review the profile, confirm next steps, and activate the partner account.</p><button onClick={()=>setSubmitted(false)}>Reset application demo</button><Link href="/partner">Explore the command center →</Link></div>:<form onSubmit={e=>{e.preventDefault();setSubmitted(true)}}><label>Your name<input required placeholder="Full name"/></label><label>Business or brand<input required placeholder="Business, practice, or creator name"/></label><label>Email<input required type="email" placeholder="you@business.com"/></label><label>Primary audience<select required defaultValue=""><option value="" disabled>Select one</option><option>Existing customer database</option><option>Professional network</option><option>Social audience</option><option>Research community</option><option>Other</option></select></label><label className="wide">How will you share POW?<textarea required rows={4} placeholder="Tell us about your audience, channels, and approach."/></label><label className="application-check wide"><input required type="checkbox"/> I will use approved creative, follow applicable permission and disclosure rules, and avoid unsupported product or medical claims.</label><button className="add-button">Submit test application →</button><small>DEMO ONLY · NO DATA LEAVES THIS BROWSER</small></form>}</div></section>
    <section className="partner-final-cta"><div><span>READY WHEN YOU ARE.</span><h2>Bring the audience.<br/>POW brings the portal.</h2></div><div><a className="button primary" href="#apply">Apply to the network</a><Link className="button ghost" href="/partner">Open the command center</Link></div></section><Footer/></main>;
}

function InfoView({view}:{view:View}){const map:Record<string,[string,string,string]>={subscribe:["Subscribe & Save","Never run out of power.","Choose 2, 4, or 6 weeks, then skip, reschedule, change quantity, pause, or cancel in the local account prototype."],partners:["POW! Partner network","Turn your reach into impact.","Durable links, privacy-minded attribution, masked customer data, and an event-ledger foundation—business rules remain TODO."],about:["About POW!","Premium energy. Documented control.","A modern research marketplace concept built around clear product organization, lot-level documentation, and easy repeat ordering."],support:["Support","We’ve got your back.","Contact, shipping, account, and policy destinations are mapped here while final promises, workflows, and service platforms remain TODO."]};const [k,t,d]=map[view]||map.about;return <main><Header/><section className="info-hero"><span className="impact-label">{k}</span><h1>{t}</h1><p>{d}</p><div><Link className="button primary" href={view==="partners"?"/partner":"/account"}>{view==="partners"?"Open command center":"Open account demo"}</Link><Link className="button ghost" href="/shop">Shop prototype</Link></div></section><section className="info-cards">{["What works now","What stays configurable","What needs approval"].map((x,i)=><article key={x}><span>0{i+1}</span><h2>{x}</h2><p>{i===0?"Responsive layouts and local interactive states.":i===1?"Pricing, discounts, cadence rules, attribution, and operational ownership.":"Product data, testing files, policies, legal copy, and all production integrations."}</p></article>)}</section><Footer/></main>}

export default function POWApp({view,slug}:{view:View;slug?:string}){if(view==="home")return <HomeView/>;if(view==="access")return <AccessView/>;if(view==="shop")return <CatalogView/>;if(view==="product")return <ProductView slug={slug}/>;if(view==="coa")return <CoaView/>;if(view==="account")return <AccountView/>;if(view==="partner")return <PartnerView/>;if(view==="partners")return <PartnersView/>;if(view==="ops")return <OpsView/>;if(view==="research")return slug?<ResearchArticleView slug={slug}/>:<ResearchView/>;if(view==="subscribe")return <SubscribeView/>;if(view==="cart")return <CartView/>;if(view==="checkout")return <CheckoutView/>;if(view==="bundle")return <BundleView/>;if(view==="tracking")return <TrackingView/>;if(view==="compare")return <CompareView/>;if(view==="bulk")return <BulkView/>;if(view==="rewards")return <RewardsView/>;if(view==="guarantee")return <GuaranteeView/>;if(view==="support")return <SupportView/>;return <InfoView view={view}/>}
